-- Deterministic local test identities and synthetic payment text.
-- Seed data for public.bank_account, 2025-2026.
BEGIN;

-- The three source/derived tables are a single local seed dataset. Clear them
-- together before reseeding so no earlier bank, MobilePay or posting rows remain.
TRUNCATE TABLE public.posteringer, public.bank_account, public.mobilepay RESTART IDENTITY;


SELECT setval(pg_get_serial_sequence('public.bank_account', 'id'), COALESCE(MAX(id), 1), MAX(id) IS NOT NULL) FROM public.bank_account;

COMMIT;
